  const {game,a,b}=context(M,role),source=put(M,game,a,'Crypt Rats'),orrery=put(M,game,a,'Chromatic Orrery');orrery.tapped=true;a.pool.C=4;const action=()=>game.activatableList(a).find(row=>row.card===source&&row.ability?.cost.manaXColorsV20),ability=action().ability,cost=game.abilityManaCost(a,source,ability.cost.mana,{ability});assert.equal(game.canPayMana(a,cost,{card:source,isAbility:true,ability},{xVal:2}),false);choice(a,(g,q)=>q.type==='chooseX'?2:undefined);assert.equal(await game.activateAbility(a,action()),false);assert.equal(a.pool.C,4);a.pool.B=2;const life=b.life;assert.equal(await game.activateAbility(a,action()),true);assert.equal(a.pool.B,0);assert.equal(a.pool.C,4);await settle(game);assert.equal(b.life,life-2);assert.equal(source.zone,'graveyard');assertGameStateInvariants(game);
