 test(role+': Bloodthorn Flail pays either mana or a discarded card through one equip action',async()=>{
  const {game,a}=context(M,role),source=put(M,game,a,'Bloodthorn Flail'),first=put(M,game,a,'Grizzly Bears'),second=put(M,game,a,'Grizzly Bears');let discard=false;const card=put(M,game,a,'Forest','hand');choice(a,(g,q)=>q.type==='chooseTargets'?[discard?second:first]:q.aiHint?.kind==='oracleEquipChoiceV20'?(discard?'discard':'mana'):q.type==='chooseCards'&&q.from?.includes(card)?[card]:undefined);a.pool.C=3;const action=()=>game.activatableList(a).find(row=>row.card===source&&row.ability?.oracleEquip);assert.equal(game.activatableList(a).filter(row=>row.card===source&&row.ability?.oracleEquip).length,1);assert.equal(await game.activateAbility(a,action()),true);assert.equal(a.pool.C,0);assert.equal(card.zone,'hand');await settle(game);assert.equal(source.attachedTo,first.iid);discard=true;assert.ok(action());assert.equal(await game.activateAbility(a,action()),true);assert.equal(card.zone,'graveyard');assert.equal(source.attachedTo,first.iid);await settle(game);assert.equal(source.attachedTo,second.iid);assert.equal(second.power,4);assertGameStateInvariants(game);
 });
 test(role+': Bloodthorn Flail rejects a cancelled or stale discard without paying or attaching',async()=>{
  const {game,a}=context(M,role),source=put(M,game,a,'Bloodthorn Flail'),host=put(M,game,a,'Grizzly Bears'),card=put(M,game,a,'Forest','hand');let stale=false;choice(a,async(g,q)=>{if(q.type==='chooseTargets')return [host];if(q.aiHint?.kind==='oracleEquipChoiceV20')return 'discard';if(q.type==='chooseCards'&&q.from?.includes(card)){if(!stale)return [];await game.move(card,'exile');await game.move(card,'hand');return [card];}});for(stale of [false,true]){assert.equal(await game.activateAbility(a,game.activatableList(a).find(row=>row.card===source&&row.ability?.oracleEquip)),false);assert.equal(source.attachedTo,null);assert.equal(card.zone,'hand');assert.equal(game.stack.length,0);}assertGameStateInvariants(game);
 });
