 test(role+': impending counts down from a noncreature enchantment and the full-cost cast has no time counters',async()=>{
  const {game,a}=context(M,role);fund(a);const c=put(M,game,a,'Overlord of the Boilerbilges','hand');const action=game.castableList(a).find(x=>x.card===c&&x.alt?.oracleImpendingV20);assert.ok(action);assert.equal(await game.castSpell(a,c,{alt:action.alt,from:'hand'}),true);await settle(game);assert.equal(c.is('Creature'),false);assert.equal(c.counters.time,4);for(let i=0;i<4;i++){await game.emit('endStep',{player:a});await settle(game);}assert.equal(c.counters.time,0);assert.equal(c.is('Creature'),true);const full=put(M,game,a,'Overlord of the Boilerbilges','hand');assert.equal(await game.castSpell(a,full,{from:'hand'}),true);await settle(game);assert.equal(full.is('Creature'),true);assert.equal(full.counters.time||0,0);assertGameStateInvariants(game);
 });
 test(role+': finality recursion preserves the graveyard object until resolution and does not follow a blinked graveyard card',async()=>{
  const {game,a}=context(M,role),c=put(M,game,a,'Relentless X-ATM092','graveyard');fund(a);let action=game.activatableList(a).find(x=>x.card===c&&x.gyAbility);assert.ok(action);assert.equal(await game.activateAbility(a,action),true);assert.equal(c.zone,'graveyard');await settle(game);assert.equal(c.zone,'battlefield');assert.equal(c.counters.finality,1);assert.equal(c.tapped,true);await game.move(c,'graveyard');if(c.zone==='exile')await game.move(c,'graveyard');action=game.activatableList(a).find(x=>x.card===c&&x.gyAbility);assert.ok(action);assert.equal(await game.activateAbility(a,action),true);await game.move(c,'exile');await game.move(c,'graveyard');await settle(game);assert.equal(c.zone,'graveyard');assertGameStateInvariants(game);
 });
